from __future__ import annotations

"""Validate record identifiers and preserve explicitly resolved source clocks."""
import math
from numbers import Number
import pandas as pd


def validate_group_identifiers(df, group_columns):
    """Reject unknown record IDs before grouping, filling or time alignment.

    Missing values, blank strings and nonfinite numeric IDs cannot identify
    a device/record/split. Object-dtype numeric values are checked as well.
    Callers validate column presence before using this helper.
    """
    if not group_columns:
        return
    if df[group_columns].isna().any().any():
        raise ValueError('Missing group identifiers must be resolved before processing')
    for column in group_columns:
        for value in df[column]:
            if isinstance(value, str) and not value.strip():
                raise ValueError('Blank group identifiers must be resolved before processing')
            if isinstance(value, Number):
                try:
                    finite = math.isfinite(value)
                except (TypeError, ValueError, OverflowError):
                    finite = False
                if not finite:
                    raise ValueError('Nonfinite or invalid numeric group identifiers must be resolved before processing')


def normalize_process_time(values,source_timezone=None):
    """Return parsed timestamps without inventing a timezone for naive input.

    Fully timezone-aware inputs convert to UTC. Naive inputs stay naive unless
    source_timezone is explicitly supplied, in which case localization must be
    unambiguous and converts to UTC. Mixed naive/aware inputs raise. Invalid
    strings become NaT so callers can reject them. Numeric clocks require an
    explicit unit conversion by the caller before using this datetime API.
    """
    if not isinstance(values,pd.Series):
        values=pd.Series(values)
    if len(values) and pd.api.types.is_numeric_dtype(values):
        raise ValueError('Numeric timestamps require an explicit unit conversion before process-time parsing')
    awareness=set()
    for value in values:
        try:
            parsed=pd.Timestamp(value)
        except (ValueError,TypeError,OverflowError):
            continue
        if not pd.isna(parsed):
            awareness.add(parsed.tzinfo is not None)
    if len(awareness)>1:
        raise ValueError('Mixed naive and timezone-aware timestamps require explicit source-clock resolution')
    if awareness=={True}:
        return pd.to_datetime(values,errors='coerce',format='mixed',utc=True)
    result=pd.to_datetime(values,errors='coerce',format='mixed')
    if source_timezone is not None:
        result=result.dt.tz_localize(source_timezone,ambiguous='raise',nonexistent='raise').dt.tz_convert('UTC')
    return result

"""Level and temporal-change features for multichannel process windows.

Preserves channel order and physical magnitude. No FFT, waveforms, implicit
unit conversion or per-window centring is used. Only finite inputs accepted.
"""
import numpy as np
import pandas as pd



def process_features(windows, channel_names, interval_seconds):
    x=np.asarray(windows,dtype=float)
    names=list(channel_names)
    if x.ndim!=3 or x.shape[1]!=len(names) or not names or len(set(names))!=len(names):
        raise ValueError("Use N x channels x time and unique channel_names")
    if x.shape[-1]<2 or not np.isfinite(x).all():
        raise ValueError("Each window needs at least two finite time points")
    if not np.isfinite(interval_seconds) or interval_seconds<=0:
        raise ValueError("interval_seconds must be positive")
    t=np.arange(x.shape[-1])*interval_seconds/3600
    centred=t-t.mean()
    slope=(x*centred).sum(axis=-1)/(centred**2).sum()
    diff=np.diff(x,axis=-1)
    blocks=[x.mean(-1),x.std(-1),x.min(-1),x.max(-1),x[:,:,-1],slope,np.abs(diff).mean(-1)]
    suffixes=["mean","std","min","max","last","slope_per_hour","mean_abs_step"]
    values=np.stack(blocks,axis=-1).reshape(len(x),len(names)*len(suffixes))
    feature_names=[f"{c}__{s}" for c in names for s in suffixes]
    return values,feature_names


def _algorithm_execute(df: pd.DataFrame, value_columns, window_id_column="window_id",
            time_column="timestamp", interval_seconds=360., **kwargs):
    """out_1 one feature row/window; out_2 schema. Complete windows required.

    Each window_id must identify one device, split and continuous interval.
    Input timestamps must be unique with exactly interval_seconds spacing.
    """
    values=[value_columns] if isinstance(value_columns,str) else list(value_columns)
    if not isinstance(df,pd.DataFrame) or not df.columns.is_unique:
        raise ValueError("A DataFrame with unique columns is required")
    if not values or len(set(values))!=len(values) or set(values)&{time_column,window_id_column}:
        raise ValueError("Distinct numeric value columns are required")
    if any(c not in df for c in values+[window_id_column,time_column]):
        raise ValueError("Missing required columns")
    if df[window_id_column].isna().any():
        raise ValueError("Missing window IDs")
    rows=[]
    feature_names=[f"{c}__{s}" for c in values for s in ["mean","std","min","max","last","slope_per_hour","mean_abs_step"]]
    for key,part in df.groupby(window_id_column,sort=False):
        part=part.copy()
        part[time_column]=normalize_process_time(part[time_column])
        part=part.sort_values(time_column)
        delta=part[time_column].diff().dt.total_seconds().iloc[1:].to_numpy()
        if part[time_column].isna().any() or not np.allclose(delta,interval_seconds,rtol=0,atol=1e-6):
            raise ValueError("Window has invalid, duplicate or discontinuous timestamps")
        a=part[values].to_numpy(dtype=float).T[None]
        f,feature_names=process_features(a,values,interval_seconds)
        rows.append({window_id_column:key,**dict(zip(feature_names,f[0]))})
    result_df=pd.DataFrame(rows,columns=[window_id_column]+feature_names)
    info_df=pd.DataFrame({"feature_name":feature_names})
    return {"out_1":result_df,"out_2":info_df}

def execute(
    df: pd.DataFrame,
    value_columns,
    window_id_column='window_id',
    time_column='timestamp',
    interval_seconds=360.0,
    **kwargs,
) -> dict[str, pd.DataFrame]:
    """从完整的多测点低频窗口提取统计与趋势特征；不处理原始声波。

    df 为长表，含数值 value_columns、window_id_column、time_column。
    每个窗口ID只对应一个设备、记录与划分；组内时钟唯一且连续。
    interval_seconds > 0（秒）。每通道7特征：均值、标准差、最小、最大、
    末值、每小时斜率、相邻点绝对差均值。保留通道顺序和物理量级。
    仅接受有限值且每窗至少2点；不自动补齐、不做逐窗去均值或归一化。
    out_1=result_df: 每窗一行特征；out_2=info_df: feature_name特征字段表。
    空输入返回明确特征列的空表；非法输入抛异常。不修改原表。依赖 numpy,pandas。
    """
    outputs = _algorithm_execute(df, value_columns, window_id_column, time_column, interval_seconds, **kwargs)
    result_df = outputs['out_1']
    info_df = outputs['out_2']
    return {'out_1': result_df, 'out_2': info_df}
